input.command:
ls export/ | head; echo "---model counts---"; python - <<'EOF'
import json,glob,collections
c=collections.Counter()
for f in glob.glob('export/*.jsonl'):
    for line in open(f,encoding='utf-8'):
        line=line.strip()
        if line:
            c[json.loads(line).get('model')]+=1
for m,n in c.most_common(): print(f"{n:7d}  {m}")
EOF

